CREATE DATABASE IF NOT EXISTS mischief_outlaws CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mischief_outlaws;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','officer') NOT NULL DEFAULT 'officer', is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE officers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, position VARCHAR(100) NOT NULL, bio TEXT NOT NULL, image_path VARCHAR(255) NULL, sort_order SMALLINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE events (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, event_date DATE NOT NULL, location VARCHAR(150) NOT NULL, description TEXT NOT NULL, image_path VARCHAR(255) NULL, status ENUM('upcoming','completed') NOT NULL DEFAULT 'upcoming', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_events_date (event_date)) ENGINE=InnoDB;
CREATE TABLE gallery (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, image_path VARCHAR(255) NOT NULL, category ENUM('touring','clubhouse','bikes','events') NOT NULL DEFAULT 'touring', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_gallery_category (category)) ENGINE=InnoDB;
CREATE TABLE merchandise (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, price DECIMAL(10,2) NOT NULL DEFAULT 0, image_path VARCHAR(255) NULL, stock INT NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE prospects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, nickname VARCHAR(50) NULL, phone_number VARCHAR(30) NOT NULL, bike_model VARCHAR(100) NOT NULL, reason_to_join TEXT NULL, status ENUM('pending','reviewed','accepted','rejected') NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_prospects_status (status)) ENGINE=InnoDB;
